INSERT OR IGNORE INTO listings (id, slug, title, description, location, city, district, listing_type, category, price, price_period, beds, baths, area, plot_area, build_year, features, images, featured, status, source_url, created_at, updated_at, published_at)
VALUES ('zpl-001', 'bebek-bogaz-manzarali-yali-dairesi', 'Bebek''te Boğaz manzaralı yalı dairesi', 'Bebek koyuna bakan tarihi bir yalının tamamı yenilenmiş orta katı. Salon cephesi baştan başa Boğaz''a açılıyor, akşam ışığı gün boyu takip edilebiliyor. Bina yönetimi güçlü, iskele kullanım hakkı daireye tanımlı.', 'Bebek Mahallesi', 'İstanbul', 'Beşiktaş', 'satilik', 'daire', 285000000, NULL, 4, 3, 310, NULL, 1962, '["Kesintisiz Boğaz manzarası","Ortak iskele kullanım hakkı","Tam yenilenmiş ıslak hacimler","Yerden ısıtma","İki araçlık kapalı otopark","24 saat güvenlik"]', '["https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=2400&q=80","https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=2400&q=80","https://images.unsplash.com/photo-1600566753086-00f18fb6b3ea?auto=format&fit=crop&w=2400&q=80","https://images.unsplash.com/photo-1505873242700-f289a29e1e0f?auto=format&fit=crop&w=2400&q=80"]', 1, 'published', NULL, '2026-09-09T15:31:35.164Z', '2026-09-09T15:31:35.164Z', '2026-09-09T15:31:35.164Z');

INSERT OR IGNORE INTO listings (id, slug, title, description, location, city, district, listing_type, category, price, price_period, beds, baths, area, plot_area, build_year, features, images, featured, status, source_url, created_at, updated_at, published_at)
VALUES ('zpl-002', 'zekeriyakoy-orman-cephesi-villa', 'Zekeriyaköy''de orman cepheli müstakil villa', 'Site içinde, arkası doğrudan ormana bakan köşe parselde konumlu. Üç katlı yapı 2021''de tamamen elden geçirildi, bodrum kat sinema ve spor alanına dönüştürüldü. Bahçe olgun ağaçlarla kapalı, komşu görüşü yok.', 'Zekeriyaköy', 'İstanbul', 'Sarıyer', 'satilik', 'villa', 92500000, NULL, 5, 4, 520, 1150, 2009, '["Orman cepheli köşe parsel","Özel havuz ve peyzajlı bahçe","Akıllı ev sistemi","Jeneratör ve su deposu","Sinema odası","Üç araçlık kapalı otopark","Site içi güvenlik"]', '["https://images.unsplash.com/photo-1613490493576-7fde63acd811?auto=format&fit=crop&w=2400&q=80","https://images.unsplash.com/photo-1580587771525-78b9dba3b914?auto=format&fit=crop&w=2400&q=80","https://images.unsplash.com/photo-1600566753086-00f18fb6b3ea?auto=format&fit=crop&w=2400&q=80","https://images.unsplash.com/photo-1560448204-e02f11c3d0e2?auto=format&fit=crop&w=2400&q=80"]', 1, 'published', NULL, '2026-09-09T15:31:35.164Z', '2026-09-09T15:31:35.164Z', '2026-09-09T15:31:35.164Z');

INSERT OR IGNORE INTO listings (id, slug, title, description, location, city, district, listing_type, category, price, price_period, beds, baths, area, plot_area, build_year, features, images, featured, status, source_url, created_at, updated_at, published_at)
VALUES ('zpl-003', 'nisantasi-butik-rezidans-dairesi', 'Nişantaşı''nda butik rezidans dairesi', 'Toplam on iki daireli bir butik rezidansın üst katında, iki cepheli bir daire. Abdi İpekçi Caddesi yürüme mesafesinde, buna rağmen sokak sessiz. Concierge hizmeti bina bünyesinde veriliyor.', 'Teşvikiye', 'İstanbul', 'Şişli', 'satilik', 'rezidans', 48750000, NULL, 3, 2, 195, NULL, 2018, '["Butik bina, on iki daire","Concierge ve resepsiyon","İki cepheli aydınlık plan","Merkezi iklimlendirme","Kapalı otopark","Yangın ve deprem yönetmeliğine uygun yapı"]', '["https://images.unsplash.com/photo-1524758631624-e2822e304c36?auto=format&fit=crop&w=2400&q=80","https://images.unsplash.com/photo-1522708323590-d24dbb6b0267?auto=format&fit=crop&w=2400&q=80","https://images.unsplash.com/photo-1484154218962-a197022b5858?auto=format&fit=crop&w=2400&q=80","https://images.unsplash.com/photo-1505873242700-f289a29e1e0f?auto=format&fit=crop&w=2400&q=80"]', 1, 'published', NULL, '2026-09-09T15:31:35.164Z', '2026-09-09T15:31:35.164Z', '2026-09-09T15:31:35.164Z');

INSERT OR IGNORE INTO listings (id, slug, title, description, location, city, district, listing_type, category, price, price_period, beds, baths, area, plot_area, build_year, features, images, featured, status, source_url, created_at, updated_at, published_at)
VALUES ('zpl-004', 'atasehir-finans-merkezi-kiralik-ofis', 'Ataşehir''de finans merkezinde kiralık ofis katı', 'A sınıfı bir kulenin tam katı, bölünmemiş açık plan. Metro çıkışına yürüme mesafesinde, otoyol bağlantısı doğrudan. Kat, kurumsal kiracının plan tercihine göre teslim edilebiliyor.', 'Barbaros Mahallesi', 'İstanbul', 'Ataşehir', 'kiralik', 'ofis', 1450000, 'ay', 0, 4, 980, NULL, 2016, '["A sınıfı kule, tam kat","Bölünmemiş açık plan","Raised floor ve kablolama altyapısı","Jeneratör ve UPS desteği","40 araçlık tahsisli otopark","LEED sertifikalı bina"]', '["https://images.unsplash.com/photo-1497366811353-6870744d04b2?auto=format&fit=crop&w=2400&q=80","https://images.unsplash.com/photo-1497366754035-f200968a6e72?auto=format&fit=crop&w=2400&q=80","https://images.unsplash.com/photo-1524758631624-e2822e304c36?auto=format&fit=crop&w=2400&q=80"]', 0, 'published', NULL, '2026-09-09T15:31:35.164Z', '2026-09-09T15:31:35.164Z', '2026-09-09T15:31:35.164Z');

INSERT OR IGNORE INTO listings (id, slug, title, description, location, city, district, listing_type, category, price, price_period, beds, baths, area, plot_area, build_year, features, images, featured, status, source_url, created_at, updated_at, published_at)
VALUES ('zpl-005', 'beykoz-tarihi-yali', 'Beykoz''da restore edilmiş tarihi yalı', 'Anadolu yakasının sakin hattında, denize sıfır konumlu tescilli yalı. Restorasyon 2019''da kurul onayıyla tamamlandı, özgün ahşap detaylar korundu. Kendi iskelesi ve tekne bağlama hakkı var.', 'Anadolu Hisarı hattı', 'İstanbul', 'Beykoz', 'satilik', 'yali', 410000000, NULL, 7, 5, 740, 1400, 1897, '["Denize sıfır, özel iskele","Kurul onaylı restorasyon","Özgün ahşap işçilik","Hamam ve kış bahçesi","Müştemilat ve personel dairesi","Beş araçlık otopark","Tam güvenlik altyapısı"]', '["https://images.unsplash.com/photo-1523217582562-09d0def993a6?auto=format&fit=crop&w=2400&q=80","https://images.unsplash.com/photo-1512917774080-9991f1c4c750?auto=format&fit=crop&w=2400&q=80","https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=2400&q=80","https://images.unsplash.com/photo-1571003123894-1f0594d2b5d9?auto=format&fit=crop&w=2400&q=80"]', 1, 'published', NULL, '2026-09-09T15:31:35.164Z', '2026-09-09T15:31:35.164Z', '2026-09-09T15:31:35.164Z');

INSERT OR IGNORE INTO listings (id, slug, title, description, location, city, district, listing_type, category, price, price_period, beds, baths, area, plot_area, build_year, features, images, featured, status, source_url, created_at, updated_at, published_at)
VALUES ('zpl-006', 'bodrum-yalikavak-deniz-manzarali-villa', 'Yalıkavak''ta deniz manzaralı taş villa', 'Marinanın üst yamacında, üç taraftan denize bakan bağımsız villa. Yerel taş ve ahşap ağırlıklı mimari, iç mekânda modern bir kurguyla birleşiyor. Sonsuzluk havuzu gün batımı yönüne konumlandırılmış.', 'Yalıkavak', 'Muğla', 'Bodrum', 'satilik', 'villa', 165000000, NULL, 5, 5, 430, 1800, 2020, '["Kesintisiz deniz manzarası","Sonsuzluk havuzu","Akıllı ev sistemi","Güneş enerjili sıcak su","Misafir evi","Marinaya beş dakika"]', '["https://images.unsplash.com/photo-1582610116397-edb318620f90?auto=format&fit=crop&w=2400&q=80","https://images.unsplash.com/photo-1571003123894-1f0594d2b5d9?auto=format&fit=crop&w=2400&q=80","https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?auto=format&fit=crop&w=2400&q=80","https://images.unsplash.com/photo-1520250497591-112f2f40a3f4?auto=format&fit=crop&w=2400&q=80"]', 1, 'published', NULL, '2026-09-09T15:31:35.164Z', '2026-09-09T15:31:35.164Z', '2026-09-09T15:31:35.164Z');

INSERT OR IGNORE INTO listings (id, slug, title, description, location, city, district, listing_type, category, price, price_period, beds, baths, area, plot_area, build_year, features, images, featured, status, source_url, created_at, updated_at, published_at)
VALUES ('zpl-007', 'cesme-alacati-sezonluk-kiralik-villa', 'Alaçatı''da sezonluk kiralık taş villa', 'Taş sokaklara yürüme mesafesinde, yüksek duvarlarla çevrili özel bahçeli villa. Avlu, gün boyu gölge alacak şekilde kurgulanmış. Haziran ve eylül arası aylık dönemlerle kiralanıyor.', 'Alaçatı', 'İzmir', 'Çeşme', 'kiralik', 'villa', 750000, 'ay', 4, 4, 260, 620, 2017, '["Özel havuz ve gölgeli avlu","Alaçatı merkeze yürüme mesafesi","Tam donanımlı mutfak","Haftalık temizlik hizmeti dahil","Kapalı otopark","Eşyalı teslim"]', '["https://images.unsplash.com/photo-1540541338287-41700207dee6?auto=format&fit=crop&w=2400&q=80","https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=2400&q=80","https://images.unsplash.com/photo-1524758631624-e2822e304c36?auto=format&fit=crop&w=2400&q=80"]', 0, 'published', NULL, '2026-09-09T15:31:35.164Z', '2026-09-09T15:31:35.164Z', '2026-09-09T15:31:35.164Z');

INSERT OR IGNORE INTO listings (id, slug, title, description, location, city, district, listing_type, category, price, price_period, beds, baths, area, plot_area, build_year, features, images, featured, status, source_url, created_at, updated_at, published_at)
VALUES ('zpl-008', 'gocek-marina-rezidans-dairesi', 'Göcek''te marina cepheli rezidans dairesi', 'Marinaya bakan alçak katlı bir sitede, iki teraslı bahçe katı dairesi. Sabah kahvesi terasla, akşam yürüyüşü marina hattıyla tamamlanıyor. Site kendi plajına ve tekne bağlama kotasına sahip.', 'Göcek merkez', 'Muğla', 'Fethiye', 'satilik', 'rezidans', 38500000, NULL, 3, 3, 175, 90, 2015, '["Marina manzarası","İki adet özel teras","Site içi plaj ve havuz","Tekne bağlama kotası","Kapalı otopark","Yıl boyu site yönetimi"]', '["https://images.unsplash.com/photo-1600047509807-ba8f99d2cdde?auto=format&fit=crop&w=2400&q=80","https://images.unsplash.com/photo-1600566753086-00f18fb6b3ea?auto=format&fit=crop&w=2400&q=80","https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=2400&q=80"]', 0, 'published', NULL, '2026-09-09T15:31:35.164Z', '2026-09-09T15:31:35.164Z', '2026-09-09T15:31:35.164Z');

INSERT OR IGNORE INTO listings (id, slug, title, description, location, city, district, listing_type, category, price, price_period, beds, baths, area, plot_area, build_year, features, images, featured, status, source_url, created_at, updated_at, published_at)
VALUES ('zpl-009', 'kas-deniz-manzarali-imarli-arsa', 'Kaş''ta deniz manzaralı imarlı arsa', 'Meis adasına bakan yamaçta, konut imarlı tek parsel. Yol, elektrik ve su altyapısı parsele kadar getirilmiş. Yaklaşık 400 m2 inşaat hakkı bulunuyor, mimari ön çalışma dosyada mevcut.', 'Çukurbağ Yarımadası', 'Antalya', 'Kaş', 'satilik', 'arsa', 34500000, NULL, 0, 0, 2400, 2400, NULL, '["Konut imarlı tek parsel","Meis adası ve deniz manzarası","Yol, elektrik ve su parselde","Yaklaşık 400 m2 inşaat hakkı","Mimari ön proje dosyada","Kaş merkeze on dakika"]', '["https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=2400&q=80","https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=2400&q=80","https://images.unsplash.com/photo-1540541338287-41700207dee6?auto=format&fit=crop&w=2400&q=80"]', 0, 'published', NULL, '2026-09-09T15:31:35.164Z', '2026-09-09T15:31:35.164Z', '2026-09-09T15:31:35.164Z');

INSERT OR IGNORE INTO listings (id, slug, title, description, location, city, district, listing_type, category, price, price_period, beds, baths, area, plot_area, build_year, features, images, featured, status, source_url, created_at, updated_at, published_at)
VALUES ('zpl-010', 'sapanca-gol-manzarali-villa', 'Sapanca''da göl manzaralı müstakil villa', 'Göl hattına bakan yamaçta, ormanla komşu tek parsel villa. İstanbul''a otoyolla bir saat, hafta sonu kullanımına ve uzaktan çalışmaya uygun. Isıtma altyapısı yıl boyu kullanım için kurgulanmış.', 'Kırkpınar', 'Sakarya', 'Sapanca', 'satilik', 'villa', 42000000, NULL, 4, 3, 340, 1600, 2019, '["Göl ve orman manzarası","Kapalı ısıtmalı havuz","Şömineli yaşam alanı","Yerden ısıtma ve doğalgaz","Fiber internet altyapısı","İstanbul''a bir saat"]', '["https://images.unsplash.com/photo-1568605114967-8130f3a36994?auto=format&fit=crop&w=2400&q=80","https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=2400&q=80","https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=2400&q=80"]', 0, 'published', NULL, '2026-09-09T15:31:35.164Z', '2026-09-09T15:31:35.164Z', '2026-09-09T15:31:35.164Z');
